      "chord_quality": "dom7",
      "function_role": "voice-leading-half-step-approach-guide-tones",
      "narrative": "Approaching the 3rd or 7th of a dominant chord by half step reinforces harmonic clarity and idiomatic bebop voice-leading. Chapter 11 p.39 prescribes: 'Lead into the 3rd or 7th by half step. This strengthens the harmony.'",
      "source_principle_ids": [],
